use crate::vector_model::PersistentVector;

pub fn run(n: i32) {
    let mut v = PersistentVector::new();
    let mut i = 0;
    while i < n {
        v = v.push_back(i);
        i += 1;
    }

    let mut transient = v.transient();
    transient.set(n / 2, n.wrapping_mul(10));
    transient.push_back(n.wrapping_mul(20));
    transient.push_back(n.wrapping_mul(30));

    let v2 = transient.persistent();

    println!("{} {}", v.size(), v2.size());
    println!("{}", v2.get(n / 2));

    if v2.size() >= 3 {
        for index in (v2.size() - 3)..v2.size() {
            print!("{} ", v2.get(index as i32));
        }
    }
    println!();
}

