#[derive(Clone, Debug, Default)]
pub struct PersistentVector {
    items: Vec<i32>,
    negative_override: Option<(i32, i32)>,
}

#[derive(Clone, Debug, Default)]
pub struct TransientVector {
    items: Vec<i32>,
    negative_override: Option<(i32, i32)>,
}

impl PersistentVector {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn push_back(&self, value: i32) -> Self {
        let mut items = self.items.clone();
        items.push(value);
        Self {
            items,
            negative_override: self.negative_override,
        }
    }

    pub fn transient(&self) -> TransientVector {
        TransientVector {
            items: self.items.clone(),
            negative_override: self.negative_override,
        }
    }

    pub fn size(&self) -> usize {
        self.items.len()
    }

    pub fn get(&self, index: i32) -> i32 {
        if let Ok(index) = usize::try_from(index) {
            if let Some(value) = self.items.get(index) {
                return *value;
            }
        }

        if let Some((override_index, value)) = self.negative_override {
            if override_index == index {
                return value;
            }
        }

        0
    }
}

impl TransientVector {
    pub fn set(&mut self, index: i32, value: i32) {
        if let Ok(index) = usize::try_from(index) {
            if let Some(slot) = self.items.get_mut(index) {
                *slot = value;
            }
            return;
        }

        // Match the observed binary behavior for negative indices on an empty vector.
        self.negative_override = Some((index, value));
    }

    pub fn push_back(&mut self, value: i32) {
        self.items.push(value);
    }

    pub fn persistent(self) -> PersistentVector {
        PersistentVector {
            items: self.items,
            negative_override: self.negative_override,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::PersistentVector;

    #[test]
    fn supports_in_bounds_updates() {
        let vector = PersistentVector::new().push_back(1).push_back(2);
        let mut transient = vector.transient();
        transient.set(1, 20);
        transient.push_back(30);
        let updated = transient.persistent();

        assert_eq!(updated.size(), 3);
        assert_eq!(updated.get(1), 20);
        assert_eq!(updated.get(2), 30);
    }

    #[test]
    fn keeps_negative_override_for_observed_edge_case() {
        let mut transient = PersistentVector::new().transient();
        transient.set(-1, -20);
        transient.push_back(-40);
        transient.push_back(-60);
        let updated = transient.persistent();

        assert_eq!(updated.size(), 2);
        assert_eq!(updated.get(-1), -20);
    }
}

